package auditlog

// The hash chain's encoding, checked against an independent implementation
// (cleat#2047). testdata/chain_vectors.json is generated by
// testdata/audit_chain_reference.py, which shares no code with chain.go; these tests
// assert this package reproduces every hash and every intermediate form in it.

import (
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"os"
	"strings"
	"testing"
	"time"

	"github.com/google/uuid"
)

type vectorFile struct {
	Version int          `json:"version"`
	Cases   []vectorCase `json:"cases"`
}

type vectorCase struct {
	Name               string       `json:"name"`
	PrevHash           string       `json:"prev_hash"`
	Record             vectorRecord `json:"record"`
	CanonicalMetadata  *string      `json:"canonical_metadata"`
	CanonicalTimestamp string       `json:"canonical_timestamp"`
	Hash               string       `json:"hash"`
}

type vectorRecord struct {
	TenantID   string  `json:"tenant_id"`
	Seq        int64   `json:"seq"`
	ID         string  `json:"id"`
	Timestamp  string  `json:"timestamp"`
	Method     string  `json:"method"`
	Path       string  `json:"path"`
	StatusCode *int64  `json:"status_code"`
	UserID     *string `json:"user_id"`
	IPAddress  *string `json:"ip_address"`
	UserAgent  *string `json:"user_agent"`
	DurationMs *int64  `json:"duration_ms"`
	Metadata   *string `json:"metadata"`
}

func (v vectorRecord) chain(t *testing.T) chainRecord {
	t.Helper()
	ts, err := time.Parse(time.RFC3339Nano, v.Timestamp)
	if err != nil {
		t.Fatalf("timestamp %q: %v", v.Timestamp, err)
	}
	ns := func(p *string) sql.NullString {
		if p == nil {
			return sql.NullString{}
		}
		return sql.NullString{String: *p, Valid: true}
	}
	ni := func(p *int64) sql.NullInt64 {
		if p == nil {
			return sql.NullInt64{}
		}
		return sql.NullInt64{Int64: *p, Valid: true}
	}
	return chainRecord{
		TenantID: uuid.MustParse(v.TenantID), Seq: v.Seq, ID: uuid.MustParse(v.ID), Timestamp: ts,
		Method: v.Method, Path: v.Path, StatusCode: ni(v.StatusCode), UserID: ns(v.UserID),
		IPAddress: ns(v.IPAddress), UserAgent: ns(v.UserAgent), DurationMs: ni(v.DurationMs), Metadata: ns(v.Metadata),
	}
}

func hashFromHex(t *testing.T, s string) [chainHashLen]byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil || len(b) != chainHashLen {
		t.Fatalf("not a %d-byte hash: %q (%v)", chainHashLen, s, err)
	}
	var h [chainHashLen]byte
	copy(h[:], b)
	return h
}

func loadVectors(t *testing.T) vectorFile {
	t.Helper()
	raw, err := os.ReadFile("testdata/chain_vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var f vectorFile
	if err := json.Unmarshal(raw, &f); err != nil {
		t.Fatal(err)
	}
	// An empty or short file would make every assertion below pass vacuously.
	if f.Version != 1 || len(f.Cases) < 10 {
		t.Fatalf("chain_vectors.json: version %d, %d cases; expected version 1 and at least 10", f.Version, len(f.Cases))
	}
	return f
}

func TestTheChainHashMatchesTheIndependentReferenceImplementation(t *testing.T) {
	f := loadVectors(t)
	for _, c := range f.Cases {
		t.Run(c.Name, func(t *testing.T) {
			rec := c.Record.chain(t)
			if got := canonicalTimestamp(rec.Timestamp); got != c.CanonicalTimestamp {
				t.Errorf("canonical timestamp %q, reference %q", got, c.CanonicalTimestamp)
			}
			if rec.Metadata.Valid {
				got, err := canonicalJSON(rec.Metadata.String)
				if err != nil {
					t.Fatalf("canonicalJSON: %v", err)
				}
				if c.CanonicalMetadata == nil || got != *c.CanonicalMetadata {
					t.Errorf("canonical metadata %q, reference %v", got, c.CanonicalMetadata)
				}
			}
			got, err := chainHash(hashFromHex(t, c.PrevHash), rec)
			if err != nil {
				t.Fatal(err)
			}
			if hex.EncodeToString(got[:]) != c.Hash {
				t.Errorf("hash %x, reference %s", got, c.Hash)
			}
		})
	}
}

// What must be equal and what must not, stated as properties rather than left to the
// fixture: the vectors say "these hashes", these say why.
func TestCanonicalisationEqualitiesAndDifferences(t *testing.T) {
	hashOf := func(mut func(*chainRecord)) [chainHashLen]byte {
		r := loadVectors(t).Cases[0].Record.chain(t)
		mut(&r)
		h, err := chainHash([chainHashLen]byte{}, r)
		if err != nil {
			t.Fatal(err)
		}
		return h
	}
	base := hashOf(func(*chainRecord) {})

	equal := map[string]func(*chainRecord){
		"a timestamp beyond microseconds":     func(r *chainRecord) { r.Timestamp = r.Timestamp.Add(999 * time.Nanosecond) },
		"the same instant in another zone":    func(r *chainRecord) { r.Timestamp = r.Timestamp.In(time.FixedZone("x", -4*3600)) },
		"metadata key order and whitespace":   func(r *chainRecord) { r.Metadata = sql.NullString{String: ` { "b" : 1 , "a" : 2 } `, Valid: true} },
		"metadata with keys in another order": func(r *chainRecord) { r.Metadata = sql.NullString{String: `{"a":2,"b":1}`, Valid: true} },
		"nothing (the control: a no-op edit)": func(*chainRecord) {},
	}
	// The two metadata forms above are equal to EACH OTHER, not to base's "{}".
	if hashOf(equal["metadata key order and whitespace"]) != hashOf(equal["metadata with keys in another order"]) {
		t.Error("metadata key order or whitespace changed the hash")
	}
	for name, mut := range equal {
		if strings.HasPrefix(name, "metadata") {
			continue
		}
		if hashOf(mut) != base {
			t.Errorf("%s changed the hash", name)
		}
	}

	// Every field, edited, must change the hash. This is what "an edited row is
	// detectable" rests on at the level of the hash.
	differ := map[string]func(*chainRecord){
		"tenant_id":            func(r *chainRecord) { r.TenantID = uuid.MustParse("22222222-2222-2222-2222-222222222222") },
		"seq":                  func(r *chainRecord) { r.Seq++ },
		"id":                   func(r *chainRecord) { r.ID = uuid.MustParse("cccccccc-cccc-cccc-cccc-cccccccccccc") },
		"timestamp (1us)":      func(r *chainRecord) { r.Timestamp = r.Timestamp.Add(time.Microsecond) },
		"method":               func(r *chainRecord) { r.Method = "PUT" },
		"path":                 func(r *chainRecord) { r.Path += "x" },
		"status_code":          func(r *chainRecord) { r.StatusCode.Int64++ },
		"status_code to NULL":  func(r *chainRecord) { r.StatusCode = sql.NullInt64{} },
		"user_id":              func(r *chainRecord) { r.UserID.String = "mallory" },
		"user_id to NULL":      func(r *chainRecord) { r.UserID = sql.NullString{} },
		"user_id to empty":     func(r *chainRecord) { r.UserID.String = "" },
		"ip_address":           func(r *chainRecord) { r.IPAddress.String = "10.0.0.2" },
		"user_agent":           func(r *chainRecord) { r.UserAgent.String += " " },
		"duration_ms":          func(r *chainRecord) { r.DurationMs.Int64++ },
		"duration_ms to NULL":  func(r *chainRecord) { r.DurationMs = sql.NullInt64{} },
		"metadata":             func(r *chainRecord) { r.Metadata = sql.NullString{String: `{"role":"admin"}`, Valid: true} },
		"metadata to NULL":     func(r *chainRecord) { r.Metadata = sql.NullString{} },
		"metadata number form": func(r *chainRecord) { r.Metadata = sql.NullString{String: `{"n":1.0}`, Valid: true} },
	}
	seen := map[[chainHashLen]byte]string{base: "the unedited row"}
	for name, mut := range differ {
		h := hashOf(mut)
		if prev, dup := seen[h]; dup {
			t.Errorf("editing %s gives the same hash as %s: that edit is undetectable", name, prev)
		}
		seen[h] = name
	}
	// ...and the previous row's hash is covered, which is what makes it a chain.
	prev := [chainHashLen]byte{1}
	r := loadVectors(t).Cases[0].Record.chain(t)
	h, _ := chainHash(prev, r)
	if h == base {
		t.Error("the previous row's hash does not change this row's hash: the rows are not chained")
	}
}

// A value cannot be moved across a field boundary. Without a length prefix,
// ("/ab", "c") and ("/a", "bc") would hash alike.
func TestNoValueCanBeShiftedAcrossAFieldBoundary(t *testing.T) {
	mk := func(path, ua string) [chainHashLen]byte {
		r := loadVectors(t).Cases[0].Record.chain(t)
		r.Path, r.UserAgent = path, sql.NullString{String: ua, Valid: true}
		h, err := chainHash([chainHashLen]byte{}, r)
		if err != nil {
			t.Fatal(err)
		}
		return h
	}
	if mk("/ab", "c") == mk("/a", "bc") {
		t.Fatal("shifting a byte from one field to the next did not change the hash")
	}
	if mk("/a", "") == mk("/a\x00", "") {
		t.Fatal("a trailing NUL was ignored")
	}
}

func TestCanonicalJSONRefusesWhatIsNotOneJSONValue(t *testing.T) {
	for _, bad := range []string{``, `{`, `{"a":1} {"b":2}`, `{"a":1}x`, `nope`} {
		if got, err := canonicalJSON(bad); err == nil {
			t.Errorf("canonicalJSON(%q) = %q, want an error", bad, got)
		}
	}
	for in, want := range map[string]string{
		`{}`:                                   `{}`,
		` { "b" : [ 1 , 2.50 ] , "a" : "x" } `: `{"a":"x","b":[1,2.50]}`,
		`"aé\n"`:                               "\"aé\\u000a\"",
		`{"k":" "}`:                            "{\"k\":\" \"}",
	} {
		got, err := canonicalJSON(in)
		if err != nil || got != want {
			t.Errorf("canonicalJSON(%q) = %q, %v; want %q", in, got, err, want)
		}
	}
}
